// Assemble the Module 4 output envelope (schema: proposal-assembly.schema.json).
const cf = $('Compute Proposal Fields').first().json;
const copied = $('Copy Template').first().json;
let draftId = null;
try { draftId = $('Create Draft').first().json.id || $('Create Draft').first().json.message?.id || null; } catch (e) {}
return [{ json: {
  client_id: cf.client_id,
  status: 'ok',
  errors: [],
  data: {
    proposal_number: cf.proposal_number,
    document_id: copied.id,
    pdf_file_name: `${copied.name}.pdf`,
    draft_id: draftId,
    draft_recipient: cf.recipient_email,
    language: cf.language,
    template_id_used: cf.template_id,
    notified_chat_id: cf.notification_chat_id
  }
} }];
